        # Flip characters in the range [start, end) and reverse the substring
        for i in range(start, end + 1):
            if self.s[i] == '0':
                self.s = self.s[:i] + '1' + self.s[i + 1:]
            else:
                self.s = self.s[:i] + '0' + self.s[i + 1:]

