import sys
from collections import defaultdict

def find_cycle(graph, src, node):
    # Do a depth-first search to find a cycle
    visited = defaultdict(bool)
    if node in visited:
        return True, len(visited)
    visited[node] = True
    depth = 0
    for neighbor in graph[node]:
        cycle, cycle_depth = find_cycle(graph, src, neighbor)
        if cycle:
            depth = max(depth, cycle_depth)
            return True, depth
        else:
            stack = [neighbor]
            cycleinating = False
            while stack:
                child = stack.pop()
                if child in visited:
                    cycle = visited[child] ^ cycleinating
                    if cycle:
                        depth = max(depth, len(cycle) - 1)
                        return True, depth
                    cycleinating = True
                visited[child] = True
                for a in graph[child]:
                    if a != src and a != node and not visited[a]:
                        stack.append(a)
    return False, depth

def main():
    input = sys.stdin.read
    data = input().split()
    n, m = map(int, data[0:2])
    graph = defaultdict(set)
    for line in range(1, m * 2, 2):
        a, b = map(int, data[line:line + 2])
        graph[a].add(b)
        graph[b].add(a)

    full_distances = []
    for node in range(n):
        full_distances.append(-1)
    for src in range(n):
        cycle, depth = find_cycle(graph, src, src)
        if cycle:
            continue
        elif depth:
            full_distances[src] = depth + 1

    while True:
        cycle, cycle_size = find_cycle(graph, -1, -1)
        if not cycle:
            break
        cycle_size -= 1
        max_cycle = max(cycle)

    for node in range(n):
        if full_distances[node] >= 0:
            continue
        marks_to_cycle = cycle_size - full_distances[node]
        if marks_to_cycle <= max_cycle:
            full_distances[node] = max_cycle + 1
        else:
            full_distances[node] = marks_to_cycle + all(full_distances)

    for ar in full_distances:
        print(ar, end=' ')
    print()

if __name__ == "__main__":
