from collections import defaultdict, deque

def add_edge(graph, u, v):
    if u not in graph:
        graph[u] = set()
    if v not in graph:
        graph[v] = set()
    graph[u].add(v)
    graph[v].add(u)

def add_edge_dict(graph, u, v, direction=False):
    if u not in graph:
        graph[u] = set()
    if v not in graph:
        graph[v] = set()
    graph[u].add(v)
    graph[v].add(u)
    if direction:
        graph[u] = frozenset(graph[u])
        graph[v] = frozenset(graph[v])

def dfs(graph, start, visited, path, paths):
    visited[start] = True
    path.append(start)
    for neighbor in graph[start]:
        if not visited[neighbor]:
            paths.append(path.copy())
            dfs(graph, neighbor, visited, path, paths)
    path.pop()
    visited[start] = False

def get_in_degree(graph):
    in_degree = {node: 0 for node in graph}
    for node in graph:
        for neighbor in graph[node]:
            in_degree[neighbor] += 1
    return in_degree

def find_cycle(graph, s):
    seen = set()
    cycle = set()
    for node in range(1, 100000):
        if node == s:
            cycle.add(node)
        if node in graph and node not in seen:
            cycle.add(node)
            stack = deque([node])
            while stack:
                current_node = stack.pop()
                for neighbor in graph[current_node]:
                    if neighbor in cycle:
                        break
                    if neighbor in graph:
                        seen.add(neighbor)
                        stack.append(neighbor)
    return cycle

def bfs(graph, start):
    visited = {start: True}
    queue = deque([start])
    while queue:
        current_node = queue.popleft()
        for neighbor in graph[current_node]:
            if neighbor not in visited:
                visited[neighbor] = True
                queue.append(neighbor)
    return visited

def get_node_distance(graph, start, end):
    distance = {start: 0}
    coordinates = [(start, 0)]
    counter = {start, end}
    while counter:
        current_node, distance = coordinates.pop()
        for neighbor in graph[current_node]:
            if neighbor in counter and (distance[neighbor] != distance[current_node] + 1 or distance[neighbor] == 0):
                return None
            if neighbor not in distance:
                distance[neighbor] = distance[current_node] + 1
                current_node_counter = counter.copy()
                current_node_counter.add(neighbor)
                coordinates.append((neighbor, distance[current_node] + 1))
            elif distance[neighbor] == distance[current_node]:
                current_node_counter = counter.copy()
                current_node_counter.discard(neighbor)
                current_node_counter.discard(start)
                coordinates.append((neighbor, distance[current_node] + 1))
    return distance

def get_topological_order(graph):
    for vertex in graph:
        max_in_degree = max(get_in_degree(graph).values())
        topological_order = deque([vertex])
        while max_in_degree != 0:
            next_node = vertex
            for neighbor in graph[vertex]:
                if get_in_degree(graph)[neighbor] == max_in_degree - 1:
                    next_node = neighbor
            max_in_degree -= 1
            topological_order.appendleft(next_node)
            for neighbor in graph[neighbor]:
                if neighbor in graph(vertex) and (get_in_degree(graph)[next_node] - 1) == get_in_degree(graph)[neighbor]:
                    get_in_degree(graph)[neighbor] = max_in_degree
        if len(topological_order) != len(graph):
            raise Exception()
    return topological_order

def check_forest(adjacency_list):
    forest = []
    components = adjacency_list
    while len(components) > 0:
        largest_component = {'vertices': set(), 'edges': []}
        for element in components:
            if largest_component['vertices'].isdisjoint(element['vertices']):
                largest_component['vertices'] = largest_component['vertices'].union(*element['vertices']) if largest_component['vertices'] else element['vertices']
                for neighbor, edge in element['edges']:
                    if largest_component['vertices'].isdisjoint(neighbor['vertices']):
                        largest_component['vertices'] = largest_component['vertices'].union(neighbor['vertices'])
                        largest_component['edges'].append((element['vertices'].isdisjoint(neighbor['vertices']), edge + (neighbor['vertices'],)))
                components.remove(element)
        forest.append(largest_component)
    return forest

