                stack[-2] = [1, stack[-2][1]]             # Branch ones after verifying right-to-left non-terminals XOR
                ops = {'|': 'AND', '&': 'OR', '^': 'XOR'}
        elif stack[-1][0] in ops.values():
            if stack[-2][1].isdigit() and stack[-1][1].isdigit():
                stack[:-3] = list(map(list, stack[:-3]))  # Resolve right-to-left nested non-terminals AND)
                stack[-3][-1] += stack[-1]                 # Merge branch expansions AND
                ops = {'|': 'AND', '&': 'OR', '^': 'XOR'}
            elif stack[-3][1].isdigit() and stack[-1][1].isdigit():
                stack[:] = list(map(list, stack))           # Resolve right-to-left nested non-terminals ANd
                stack[1][0], stack[0][-1] = 1, stack[0][-1]  # Conver branch expansions AND
                ops = {'|': 'AND', '&': 'OR', '^': 'XOR'}
            elif stack[-3][1].isdigit() and not stack[-2][1].isdigit():
                stack[:] = list(map(list, stack))           # Resolve until omitting only one of the left-to-right nesting nested non-terminals AND OR
                stack[1], stack[2][0], stack[0][-1] = 1, stack[0][-1], 1
                stack = list(map(list, stack))              # Reshoot optimally but skipping the left-to-right nesting nested nonterminals in the parent level
                ops = {'|': 'AND', '&': 'OR', '^': 'XOR'}
            else:
                stack[:] = list(map(list, stack))           # ompute until omitting only one of the right-to-left nesting nested non-terminals AND OR
                ops = {'|': 'AND', '&': 'OR', '^': 'XOR'}

    if stack[-1][0].isdigit():
        return int(stack[-1][1]) != len(stack) - 2
