import sys

def evaluate_formula(formula):
    if formula == "0":
        return "0"
    elif formula == "1":
        return "1"
    elif formula == "?":
        return "?"  # The resulting value is indeterminate without a comparison
    else:
        parts = formula.split("&")
        if len(parts) == 1:
            # AAA | BBB form
            parts.append(formula)
        elif len(parts) == 2:
            # AAA & BBB form
            parts.append(parts[0] + " | " + parts[1])
        else:
            # AAA & BBB & CCC form
            for i in range(1, len(parts), 2):
                # Split first and second part
                part1 = eval("".join(parts[i + 1:]).replace("^", "").replace("|", ""))
                part2 = eval("".join(parts[i:]).replace("^", "").replace("|", ""))
                # Check if they match
                if part1 == part2:
                    parts.append("1" if part1 == "1" else "0")
                else:
                    parts.append("0")

        return "".join(parts)

