from functools import lru_cache

def flip_and_reverse(s):
    return ''.join('1' if ch == '0' else '0' for ch in reversed(s))

def next_smaller_string(s, index):
    # Calculate the number of 0's and 1's from index to the end of the string
    left_ones = (1 - s[index:].count('0')) // 2
    right_twenties = (sum(c > '9' for c in s[index + 1:]) * 2 // 10)

    # If we can flip and reverse the substring including the current index, try it
    if left_ones + right_twenties >= 0:
        return flip_and_reverse(s[:index] + '0' + s[index:-1] + '2' + s[-1:])
    else:
        # radd the flip and reverse back over everything before the index
        return '1' * index + '0' + flip_and_reverse(s[:index] + '1' + s[index:-1] + '2' + s[-1:]) + '1' * (len(s) - index)

@lru_cache(maxsize=None)
def get_smallest_string(s):
    if '1' not in s:
        return s
    half = (len(s) + 1) // 2
    while half > 0:
        i = half
        j = len(s) - half
        if s[i - 1:i] == s[i:j]:
            return next_smaller_string(s, i - 1)
        half -= 1
    return s

