def find_smallest_string(s, T):
    smallest_strings = [s]
    for _ in range(T - 1):
        candidates = []
        for i in range(len(s)):
            for j in range(i, len(s)):
                substr = s[i:j+1]
                if len(set(substr)) == 1:
                    candidate = flip_and_reverse(substr)
                    candidate_s = candidate.center(len(candidate), '0')[::-1]
                    candidates.append(candidate_s)
        smallest_strings = sorted(candidates)[:min(len(candidates), len(s) // 2)]

    return ''.join(smallest_strings)

