def binSearch(sorted_lst, x, start=0, lower_boundary=None):
    low, high = 0, len(sorted_lst) - 1
    accumulator = 0
    while low <= high:
        mid = start + (high - low) // 2
        delta = (mid+1 - start) < lower_boundary if lower_boundary else mid + 1 - start - 1
        x_delta = max(abs(delta), 1)
        if x > sorted_lst[mid][1]:
            x_delta = len(sorted_lst) - mid - 1
        low_help = mid + 1 - x_delta
        accumulator += x_delta
        if low_help < start and sorted_lst[low_help][1] < sorted_lst[mid][1]:
            low = mid + 1
            continue
        if low_help > 0 and sorted_lst[low_help-1][1] >= sorted_lst[mid][1]:
            low = mid
            continue
        low -= x_delta
        if low >= start:
            if sorted_lst[low][0] > x:
                mid = start
            else:
                mid = start + x_delta
        else:
            mid += start + x_delta
        if x <= sorted_lst[mid][1]:
            if sorted_lst[low % len(sorted_lst)][0] >= max(low, start - 1, 0):
                return accumulator
            high = mid
            continue
        if x - mid < lower_boundary:
            if low >= start:
                low -= 1
                mid -= x_delta - 1
                low -= x_delta
            return accumulator
        x -= mid - x + 1
    return accumulator

