def max_common_divisor(l, r, k, m):
    if k == 2:
        return gcd(l, r)
    elif k == 3:
        return gcd(l, gcd(r, m))
    else:
        smaller = min(l, r)
        larger = max(l, r)
        shift = (larger - smaller + k - 1) // k
        while shift > 0:
            l, r = l // shift, r // shift
            if l != r:
                shift -= 1
        remainder = 1
        while remainder < m:
            remainder = (l + remainder * m) % m
        return remainder // shift % m

def gcd(a, b, m = 1):
    while b:
        a, b = b, a % b
    return a * pow(m, -1 % (m-2), m)

