            j = i + 1
            while elements[j] != ")":
                j += 1
            inner = elements[i+1:j]
            for char in inner:
                if stack:
                    for _ in range(len(stack)):
                        stack.append(char)
                        i += 1
                else:
                    stack.append(char)
                    i += 1
            elements = elements[:i] + inner + elements[j+1:]
        else:
            stack.append(elements[i])
            i += 1

