        return [(A,polygon.FindIntersection(1.05*(AB[0]-A[0]), AB[1]-A[1], 2,12)-A) for C in chain(AF, [A], AF) if result]

    def match_segments(self):
        if self.chords is not None and self.permutation is not None:
            return reversed(self.chords)
        return None

    def find_out_intervals(self, segments):
        if self.chords is None or self.permutation is None or len(segments) == 0:
            return []
        grid = [[] for h in range(self.arc_count(segments[0][1], segments[0][3]) + 1)]
