from collections import defaultdict

def find_minimum_string(s):
    n = len(s)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + s[i] * (1 if s[i] == '0' else -1)
    prefix_count = defaultdict(lambda: (-(1<<29), (1<<29)))
    answer = ''
    for i in range(n + 1):
        answer = ''
        for j in range(i + 1, n + 1):
            if (prefix_sum[j] - prefix_sum[i - 1]) == (1 if s[i - 1] == '0' else -1):
                if i == 1:
                    if prefix_count[(prefix_sum[j], j)][0] <= prefix_count[(prefix_sum[i - 1], i - 1)][0]:
                        answer = s[:j]
                        break
                    if answer == '':
                        answer = s[:j - 1]
                elif prefix_count[prefix_sum[i - 1]][0] >= prefix_count[prefix_sum[j]][0]:
                    answer = s[:max(i - 1, j - 1)]
                    break
                else:
                    answer = (answer[-1] + answer[-2] + answer[-1] != '0') * answer[opposite(s[(i - 1) % len(s)] != '0')]
            prefix_count[prefix_sum[j]][opposite(s[j] != '0')] = max(prefix_count[prefix_sum[j]][opposite(s[j] != '0')], (1 if s[j] == '0' else 1 - 2 * prefix_sum[j]), (1 if s[j] == '0' else 1 - 2 * prefix_sum[j]))
    return answer

def opposite(b):
    return (1 if b else 0)

t = int(input().strip())
for _ in range(t):
    s = input().strip()
    print(find_minimum_string(s))
