def evaluate_expression(formula):
    stack = []
    for char in formula:
        if char == "'":
            stack.append(True)
        elif char == ",":
            stack.append("1" == ' '.join(stack).count("1"))
        elif char == "!":
            stack[-1] = not stack[-1]
        elif char == "}":
            last_expr, formula, i = stack[-2], stack[-1], stack.pop()
            if last_expr and i == True:
                stack.pop() # go up one level
            else:
                stack.append(last_expr or i)
        elif char == "{":
            if stack: stack.append(None) # go down one level
    return stack[0]

def is_distinguishable(n, formula):
    formula_str = formula.replace('?', '0')
    return evaluate_expression(formula_str) != evaluate_expression(formula_str.replace('1', '1').replace('0', '1'))

n = int(input().strip())

if is_distinguishable(n, input()):
    print('YES')
