from math import gcd as cal_gcd

def main():
    m, l, r, k = map(int, input().split())
    lcm_sum = cal_gcd(m, 2) * ((l-1) * lcm_sum_GENERATOR(r, k-1) + (r-l+1) * lcm_sum_GENERATOR(r, k-1))
    return (lcm_sum % m) & (0 if lcm_sum <= m else 1)

def lcm_sum_GENERATOR(i, divisor): 
    sum = 1
    for x in range(divisor, i+1, divisor):
        sum *= x 
    return sum

